programs.haiku:
"""Opening-delimiter detector for layer 15's MLP write, component 1088.

What it does: the component is near zero on most tokens. It is positive on tokens
that OPEN a quoted or embedded span, most strongly where a string is nested inside
code or JSON (an escaped quote \\" , shell or template openers like "$( and ${),
then fullwidth opening brackets, then a colon that introduces a value, then plain
quote and backtick openers. It is negative on code-style list and object openers
([ , ][ , ){ , {"). Everything else, closing tokens and ordinary words, predicts 0.

The values are rough means per token type, read off the activations of 1536
training rows; no context beyond the current token is used.
"""
import re

READS = ()

ESCAPED_QUOTE = 5.0       # \" : a string nested inside code, JSON or a shell command
EMBED_OPENER = 4.0        # "$( "${ ${ : shell / template expansion openers
CJK_BRACKET = 4.0         # fullwidth opening brackets （ 「 『
COLON = 1.5               # a colon introducing a value
QUOTE_OPENER = 1.5        # " ' ` opening a quotation, optionally after a space, paren or =
CODE_OPENER = -1.0        # [ and JSON / list openers, which sit at negative values

COLONS = {':', '：', ':\n', ' :', '":'}
EMBED = {' "$', '"$', '(${', ' "${', ' "$(', '="${', ' $('}
CODE = {'[', ' [', '][', '){', ' {"'}
QUOTE_OPEN_RE = re.compile(r' ?[("\'`=\[{]*["\'`]+[$({\[]*')


def value_of(tok):
    if '\\"' in tok:
        return ESCAPED_QUOTE
    if tok in EMBED:
        return EMBED_OPENER
    if tok in ('（', '「', '『'):
        return CJK_BRACKET
    if tok in COLONS:
        return COLON
    if tok in CODE:
        return CODE_OPENER
    if QUOTE_OPEN_RE.fullmatch(tok) and tok not in ('"', "'", '`'):
        return QUOTE_OPENER
    return 0.0


def step(carry, prefix, upstream):
    return None, value_of(prefix.token_strings[-1])

"""Conclusion connectives: a strong negative response on the word that opens a conclusion.

Component: layers.15.mlp.down_proj, rank-one unit 1095. Almost everywhere it is near zero.
It goes strongly negative on the words that introduce an inference in running text:

- sentence-initial "So", "Therefore", "Thus", "Hence" (about -3.5 to -4.2),
- lowercase "therefore", "thus", "hence" (about -2.8 to -3.1),
- "so" meaning "therefore", as in ", so ..." or "and so ..." (about -3.1),
- Chinese "因此" (about -3.6).

Two weaker effects: the intensifier "so" ("so much", "is so") is only slightly negative,
and the word right after a connective dips a little.

The program needs no memory beyond the previous token. It reads the current word and,
if it is in the same document, the word before it.
"""

READS = ()

CAPITALISED = {"So", "Therefore", "Thus", "Hence"}
LOWERCASE = {"therefore", "thus", "hence"}
CONNECTIVES = CAPITALISED | LOWERCASE | {"so", "因此"}
# What may stand before a "so" that means "therefore" (a clause boundary) rather than "so much".
CLAUSE_BEFORE = {"", ",", ".", ";", ":", "!", "?", ")", '"', "and", "→"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    documents = prefix.document_ids
    t = len(tokens) - 1
    word = tokens[t].strip()
    same_document = t >= 1 and documents[t - 1] == documents[t]
    before = tokens[t - 1].strip() if same_document else ""

    if word in CAPITALISED:
        value = -3.8
    elif word in LOWERCASE:
        value = -3.0
    elif word == "因此":
        value = -3.6
    elif word == "so":
        value = -3.1 if before in CLAUSE_BEFORE else -0.5
    elif before in CONNECTIVES:
        value = -0.5
    else:
        value = 0.0
    return carry, float(value)

"""Layer 15, MLP hidden unit 1096, read as a "getting rid of something" detector.

The component is almost entirely that one MLP hidden unit (its output vector is
dominated by the unit's own weight), written back into the residual stream. Its output
direction makes the next word more likely to be a removal verb ("remove", "delete",
"discard", "eliminate", "quit", "leave") and less likely to be "fill". So it is on when
the text is in the middle of a removing, deleting, discarding or leaving event, most
strongly on the removal verb itself.

This program guesses the activation from the words alone:
  - a strong removal verb (remove, delete, discard, eliminate, ...) predicts 3;
  - a weaker removal word (leave, cut, drop, off, out, away, ...) predicts 0.5;
  - a removal word one or two tokens back, in the same document, predicts 0.2;
  - anything else predicts 0.
Lemmas come from WordNet, so "removed", "removes" and "removing" all count. Most of the
activation's variance is spread over ordinary tokens and is not captured by any word list,
so this explains only about 1% of it. A full per-token lookup table reaches under 1% out of
sample, so the word lists are not missing a simple table.
"""

import wordnet

READS = ()

STRONG = {"remove", "delete", "discard", "eliminate", "abolish", "erase", "purge",
          "dismiss", "scrap", "discontinue", "rid"}
WEAK = {"cancel", "quit", "leave", "withdraw", "drop", "cut", "reduce", "clear", "wipe",
        "off", "out", "away", "exit", "depart", "expel", "oust", "dispose", "shed",
        "prune", "trim", "dissolve", "resign", "retire", "cease", "destroy", "kill"}

_LEMMAS = {}


def _lemmas(token):
    """The WordNet base forms of a word (lower case, no spaces), cached."""
    if token not in _LEMMAS:
        word = token.strip().lower()
        _LEMMAS[token] = set(wordnet.base_forms(word)) | {word} if word.isalpha() else {word}
    return _LEMMAS[token]


def _is_strong(token):
    return bool(_lemmas(token) & STRONG)


def _is_removal(token):
    return bool(_lemmas(token) & (STRONG | WEAK))


def step(carry, prefix, upstream):
    t = prefix.position
    word = prefix.token_strings[t]
    if _is_strong(word):
        return carry, 3.0
    if _is_removal(word):
        return carry, 0.5
    value = 0.0
    for i in (t - 1, t - 2):
        if i >= 0 and prefix.document_ids[i] == prefix.document_ids[t] and _is_removal(prefix.token_strings[i]):
            value = 0.2
    return carry, value

"""
Layer 15 MLP down-projection, component 1103: a "quality attribute is coming next" cue.

The component runs negative where the model is about to write an abstract quality or
performance attribute (efficiency, reliability, security, quality, durability, speed ...).
The program marks the words that set such a phrase up, with fitted mean activations:
  * the verbs improve / enhance / ensure / increase / maintain (about -2),
  * the function words just after them, "improve [the] ..." (about -0.7),
  * the "of" in "sense of", "lack of", "level of", "degree of" (about -2),
  * degree words high / low / more / less / better / poor (about -0.75),
  * code operators (==, !=, ===, isinstance ...), mildly positive (about +1.2), since the
    next token there is code rather than an attribute noun.
Everything else predicts 0. These cues explain only about 1.5% of the activation's variance
on eval rows: most of it depends on context that no word list captures.
"""

READS = ()

IMPROVE_VERBS = {
    "improve", "improves", "improved", "improving", "enhance", "enhances", "enhanced",
    "enhancing", "ensure", "ensures", "ensured", "ensuring", "boost", "maintain",
    "maintains", "maintaining", "increase", "increases", "increased", "increasing",
    "optimize", "promote", "reduce", "reduced", "raise", "strengthen",
}
DEGREE_NOUNS = {
    "sense", "lack", "feeling", "degree", "level", "levels", "standards", "importance",
    "loss", "ease", "touch", "extent", "amount", "measure",
}
DEGREE_ADJECTIVES = {
    "high", "higher", "highest", "low", "lower", "lowest", "more", "less", "better",
    "greater", "poor", "excellent", "good", "great", "very", "highly", "extremely",
}
FUNCTION_WORDS = {"the", "a", "an", "its", "their", "both", "and", "or", ",", "of", "to"}
CODE_OPERATORS = {"==", "!=", "===", "!==", ">=", "<=", "+=", "isinstance"}


def _words(prefix, count):
    """The newest `count` words before this position, in the same document, lower-cased."""
    lo = max(0, prefix.position - count)
    same = [
        prefix.token_strings[i].strip().lower()
        for i in range(lo, prefix.position)
        if prefix.document_ids[i] == prefix.document_ids[-1]
    ]
    return same


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = _words(prefix, 4)
    previous = before[-1] if before else ""
    value = 0.0
    if word in IMPROVE_VERBS:
        value = -2.1
    elif word == "of" and previous in DEGREE_NOUNS:
        value = -2.0
    elif word in FUNCTION_WORDS and any(w in IMPROVE_VERBS for w in before):
        value = -0.7
    elif word in DEGREE_ADJECTIVES:
        value = -0.75
    elif prefix.token_strings[-1].strip() in CODE_OPERATORS:
        value = 1.2
    return carry, value

"""Life-story chronology detector: layers.15 MLP hidden unit 1121.

What the component is: nearly all of it is one hidden unit of layer 15's MLP,
so its activation is that unit's value. It goes negative in text that narrates
a person's life in time order ("Career", "later", "became", "joined",
"After ... he ...", "born ... was ... served"), most strongly in encyclopedic
biographies. Elsewhere it stays near zero, with weak positive values on
status and description words ("former", "only", "first", "youngest").

What this program does: each token gets a score for how much it belongs to a
biographical narrative, and the value is a running average of those scores,
restarted at each new document.
  - career and life-event words (Career, later, became, joined, began, moved,
    After, During, War, ...) push the value down the most;
  - third-person narrative pronouns (He, she, his, her) push it down;
  - narrative connectives (was, In, then, also) push it down a little;
  - status and description words (former, only, first, youngest, starring)
    push it slightly up.
The running average keeps the value low through a stretch of biography.
"""

READS = ()

LIFE_EVENT = {
    "Career", "career", "Later", "later", "Early", "early", "became", "joined",
    "began", "moved", "went", "grew", "After", "after", "Following", "following",
    "During", "during", "subsequently", "eventually", "thereafter", "continued",
    "spent", "gained", "renamed", "decades", "centuries", "veteran", "Veteran",
    "War", "war", "served", "worked", "started", "graduated", "married", "died",
    "decided", "came", "century",
}
PRONOUN = {"He", "he", "She", "she", "His", "his", "Her", "her"}
LINK = {"was", "In", "then", "also"}
STATUS = {"former", "only", "first", "youngest", "Living", "starring", "third", "but"}

# Score per token, as fitted to the component's activations (per-token units).
WEIGHT = {"life": -3.1, "pronoun": -1.8, "link": -1.4, "status": 0.5}
KEEP = 0.7  # share of the running value carried from the previous token


def token_score(token):
    """The weight of one token: how strongly it marks a life narrative."""
    word = token.strip()
    if word in LIFE_EVENT:
        return WEIGHT["life"]
    if word in PRONOUN:
        return WEIGHT["pronoun"]
    if word in LINK:
        return WEIGHT["link"]
    if word in STATUS:
        return WEIGHT["status"]
    return 0.0


def step(carry, prefix, upstream):
    """The running value at the newest token; restarts at each new document."""
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    previous = 0.0 if carry is None or new_doc else carry
    value = KEEP * previous + (1 - KEEP) * token_score(prefix.token_strings[-1])
    return value, float(value)


def main():
    """Prints the running value over a short biographical sentence."""
    tokens = ["Career", " later", " he", " was", " in", " the", " army", ".", " Hello"]
    value = 0.0
    for token in tokens:
        value = KEEP * value + (1 - KEEP) * token_score(token)
        print(f"{token!r:12} {value:+.3f}")


if __name__ == "__main__":
    main()

"""Layer 15 MLP down_proj, component 1137.

What it responds to: pronouns that stand for a person or thing and that point back
to something already named, above all possessive determiners ("his", "their", "her",
"its", "your", "our", "my"), then reflexive "own"/"themselves"/"itself", then subject
pronouns that open a relative or subordinate clause ("the things you hope for",
"what they need", "the change I made"). Its output pushes the next-token guess
toward "own", "themselves", "itself" and "their", so it is strongest where a
possessive or reflexive is due.

This program is a lookup by word class: each token gets a fixed value, and
subject pronouns get a higher value after a relative or subordinating word.
Everything else gets 0. It ignores the long tail of small, context-dependent
values, which carries most of the variance.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Possessive determiners, with the mean activation seen for each.
POSSESSIVE = {
    "his": 5.3, "their": 4.6, "her": 4.2, "your": 3.9, "thy": 3.5,
    "its": 3.1, "our": 3.1, "my": 2.9,
}
# Reflexive and "own" forms, which the component's output promotes.
REFLEXIVE = {"own": 2.0, "themselves": 2.0, "itself": 2.0, "himself": 2.0, "herself": 2.0}
# Subject pronouns, and a higher value when they open a relative or subordinate clause.
SUBJECT = {"i", "you", "he", "she", "they", "we", "it"}
CLAUSE_OPENERS = {"that", "what", "which", "how", "when", "where", "as", "because", "if", "since"}
OBJECT = {"him", "them", "me", "us"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2].strip() if prefix.position > 0 else ""
    if word in POSSESSIVE:
        value = POSSESSIVE[word]
    elif word in REFLEXIVE:
        value = REFLEXIVE[word]
    elif word.lower() in SUBJECT:
        value = 3.0 if before.lower() in CLAUSE_OPENERS else 0.7
    elif word.lower() in OBJECT:
        value = 0.5
    elif word == "'s" or word == "’s":
        value = 1.3
    elif word.lower() == "who":
        value = -1.3
    else:
        value = 0.0
    return carry, float(value)

"""Pre-verbal "set-up" words: modals, adverbs and infinitive "to" that come just before a verb.

Layer 15's MLP has a component that reads its hidden state and writes a small amount into the
residual stream. Its activation is largest on the words that set up a bare verb (or predicate)
as the next word:
  - modal verbs (can, may, must, should, will, would, could, might): high, but much lower
    right after I / you / we (e.g. "you can", "I can");
  - adverbs that sit between a subject or auxiliary and its verb (also, not, only, then, just,
    already, still, really, ...) and -ly adverbs (easily, potentially, ...): highest right after
    a modal or do-support ("can also", "will not", "does not");
  - "to" when it introduces an infinitive after a verb or adjective that takes one ("try to",
    "seems to", "likely to"); "to" after motion or prepositional uses ("go to") stays low;
  - relative and linking words (that, which, who, where, how, why) and have/has/had: moderate;
  - forms of "be" (is, was, been, ...): slightly negative; everything else: near the mean.

The rule is a lookup on the current word and the word before it, with fixed levels. It
explains only a small part of the activation: the rest is spread thinly over almost every
token and depends on context this program does not read.
"""
from collections.abc import Mapping

READS: tuple = ()

MODALS = {"can", "may", "must", "should", "will", "would", "could", "might", "shall"}
AUXILIARIES = MODALS | {"do", "does", "did", "have", "has", "had"}
ADVERBS = {"also", "not", "then", "only", "just", "still", "already", "always", "never",
           "often", "really", "very", "now", "thus", "therefore", "so", "well", "even",
           "too", "again", "most", "more", "actually", "easily", "readily"}
INFINITIVE_TAKERS = {"try", "tried", "trying", "want", "wants", "wanted", "need", "needs",
                     "needed", "seem", "seems", "seemed", "likely", "able", "going", "supposed",
                     "expected", "designed", "meant", "allowed", "failed", "hard", "easy",
                     "continue", "required", "attempt"}
RELATIVES = {"that", "which", "who", "whom", "where", "when", "how", "why"}
HAVE = {"have", "has", "had"}
BE = {"be", "been", "is", "was", "are", "were", "am"}
PERSONAL = {"i", "you", "we", "me", "my", "your", "our"}
REST = 0.15


def word(text: str) -> str:
    return text.strip().lower()


def is_ly_adverb(w: str) -> bool:
    return w.isalpha() and w.endswith("ly") and len(w) > 4


def activation(prev: str, cur: str) -> float:
    if cur in MODALS:
        return 1.2 if prev in PERSONAL else 2.6
    if cur == "to":
        return 2.5 if prev in INFINITIVE_TAKERS else 0.6
    if cur in ADVERBS or is_ly_adverb(cur):
        if prev in AUXILIARIES:
            return 4.0
        return 3.0 if is_ly_adverb(cur) else 2.2
    if cur in RELATIVES:
        return 1.6
    if cur in HAVE:
        return 1.2
    if cur in BE:
        return -0.7
    if cur in PERSONAL:
        return -0.3
    return REST


def step(carry, prefix, upstream: Mapping):
    cur = word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = word(prefix.token_strings[-2]) if same_doc else ""
    return carry, float(activation(prev, cur))
